// Not Vite's dev server: a stand-in for its Node code, written for this fixture. It writes a built-in's prototype and a global under keys nothing decides and
// reaches a Solid action, as the walk finds Vite's own `dist/node` (code it generates, and packages it loads) to be a writer of any name.
import { action } from "solid-js";
const run = () => { void action(function* () {})(); };
export function install(key, value) {
  Array.prototype[key] = function () { run(); return value; };
  globalThis[key] = value;
}
